fn summarise(text: Str) -> Str {
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;

  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };

    let sc = statuses.get(e.status).unwrap_or(0);
    statuses.insert(e.status, sc + 1);

    let pc = paths.get(e.path).unwrap_or(0);
    paths.insert(e.path, pc + 1);

    total = total + e.size;

    if e.status >= 500 && e.status < 600 {
      let ec = errs.get(e.ip).unwrap_or(0);
      errs.insert(e.ip, ec + 1);
    }
  }

  let mut lines: List<Str> = [];

  for s in statuses.keys() {
    let c = statuses.get(s).unwrap_or(0);
    lines.push(s.to_str() + " " + c.to_str());
  }

  lines.push("bytes " + total.to_str());

  let mut top = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > top_n {
      top = p;
      top_n = c;
    }
  }
  lines.push("top " + top + " " + top_n.to_str());

  let mut ents: List<Ent> = [];
  for ip in errs.keys() {
    let n = errs.get(ip).unwrap_or(0);
    ents.push(Ent { ip: ip, n: n });
  }
  ents.sort_by(|a: Ent, b: Ent| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for e in ents {
    lines.push("errors " + e.ip + " " + e.n.to_str());
  }

  lines.join("\n")
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  Ok(summarise(text))
}

struct Entry { status: Int, size: Int, ip: Str, path: Str }

fn parse_line(line: Str) -> Option<Entry> {
  let q = line.split("\"");
  if q.len() != 3 { return None; }
  let head = q[0].split(" ");
  if head.len() != 6 || !head[3].starts_with("[") || head[5] != "" { return None; }
  let req = q[1].split(" ");
  if req.len() != 3 { return None; }
  let tail = q[2].trim().split(" ");
  if tail.len() != 2 { return None; }
  let status = tail[0].parse_int()?;
  let size = if tail[1] == "-" { 0 } else { tail[1].parse_int()? };
  Some(Entry { status: status, size: size, ip: head[0], path: req[1].split("?")[0] })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errors: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    total = total + e.size;
    if e.status >= 500 && e.status <= 599 {
      errors.insert(e.ip, errors.get(e.ip).unwrap_or(0) + 1);
    }
  }

  let mut out: Str = "";
  for code in statuses.keys() {
    out = out + code.to_str() + " " + statuses.get(code).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";

  let mut top: Str = "";
  let mut best = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > best { best = c; top = p; }
  }
  out = out + "top " + top + " " + best.to_str() + "\n";

  let mut ips: List<Str> = errors.keys();
  ips.sort_by(|a, b| {
    let ca = errors.get(a).unwrap_or(0);
    let cb = errors.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  for ip in ips {
    out = out + "errors " + ip + " " + errors.get(ip).unwrap_or(0).to_str() + "\n";
  }
  Ok(out)
}

struct Ent { ip: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();

  let mut sc: Map<Int, Int> = Map::new();
  let mut total = 0;
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();

  for line in text.lines() {
    let parts = line.split("\"");
    if parts.len() != 3 { continue; }

    let head = parts[0];
    let ip = head.split(" ")[0];

    let req = parts[1].split(" ");
    if req.len() != 3 { continue; }
    let path = match req[1].find("?") {
      Some(i) => req[1].slice(0, i),
      None => req[1],
    };

    let tail = parts[2].trim().split(" ");
    if tail.len() != 2 { continue; }
    let Some(st) = tail[0].parse_int() else { continue; };

    let mut size = 0;
    if tail[1] != "-" {
      let Some(n) = tail[1].parse_int() else { continue; };
      size = n;
    }

    let c = sc.get(st).unwrap_or(0);
    sc.insert(st, c + 1);
    total = total + size;

    let pc = paths.get(path).unwrap_or(0);
    paths.insert(path, pc + 1);

    if st >= 500 && st < 600 {
      let ec = errs.get(ip).unwrap_or(0);
      errs.insert(ip, ec + 1);
    }
  }

  let mut out = "";
  for st in sc.keys() {
    out = out + st.to_str() + " " + sc.get(st).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";

  let mut top = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > top_n {
      top = p;
      top_n = n;
    }
  }
  out = out + "top " + top + " " + top_n.to_str() + "\n";

  let mut ents: List<Ent> = [];
  for ip in errs.keys() {
    ents.push(Ent { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  ents.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for e in ents {
    out = out + "errors " + e.ip + " " + e.n.to_str() + "\n";
  }

  Ok(out)
}

struct Parsed { ip: Str, path: Str, status: Int, size: Int }

struct Hit { ip: Str, n: Int }

fn parse_size(s: Str) -> Option<Int> {
  if s == "-" { Some(0) } else { s.parse_int() }
}

fn parse_line(line: Str) -> Option<Parsed> {
  let q = line.split("\"");
  if q.len() != 3 { return None; }
  let head = q[0];
  if !head.contains("[") { return None; }
  let hp = head.split(" ");
  let ip = hp[0];
  if ip == "" { return None; }
  let rq = q[1].split(" ");
  if rq.len() != 3 { return None; }
  let raw = rq[1];
  let pq = raw.split("?");
  let path = pq[0];
  let parts = q[2].trim().split(" ");
  if parts.len() != 2 { return None; }
  let st = parts[0];
  let sz = parts[1];
  let status = st.parse_int()?;
  let size = parse_size(sz)?;
  Some(Parsed { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut by_status: Map<Int, Int> = Map::new();
  let mut by_path: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
