  for line in text.lines() {
    let Some(p) = parse_line(line) else { continue; };
    let c = by_status.get(p.status).unwrap_or(0);
    by_status.insert(p.status, c + 1);
    total = total + p.size;
    let pc = by_path.get(p.path).unwrap_or(0);
    by_path.insert(p.path, pc + 1);
    if p.status >= 500 && p.status <= 599 {
      let ec = errs.get(p.ip).unwrap_or(0);
      errs.insert(p.ip, ec + 1);
    }
  }

  let mut out: Str = "";
  for s in by_status.keys() {
    let n = by_status.get(s).unwrap_or(0);
    out = out + s.to_str() + " " + n.to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";

  let mut top_path: Str = "";
  let mut top_n: Int = 0;
  for p in by_path.keys() {
    let n = by_path.get(p).unwrap_or(0);
    if n > top_n {
      top_path = p;
      top_n = n;
    }
  }
  if top_n > 0 {
    out = out + "top " + top_path + " " + top_n.to_str() + "\n";
  }

  let mut hits: List<Hit> = [];
  for ip in errs.keys() {
    hits.push(Hit { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  hits.sort_by(|a: Hit, b: Hit| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for h in hits {
    out = out + "errors " + h.ip + " " + h.n.to_str() + "\n";
  }

  Ok(out.trim())
}

