import http.client
import json
import os
import urllib.error
import urllib.parse
import urllib.request

MAX_ATTEMPTS = 3
TIMEOUT = 30


def find_records_path(input_dir):
    for cand in (os.path.join(input_dir, "input", "records.jsonl"),
                 os.path.join(input_dir, "records.jsonl")):
        if os.path.isfile(cand):
            return cand
    return os.path.join(input_dir, "input", "records.jsonl")


def parse_records(path):
    """Return (invalid_line_numbers, {id: (version, line_text)}).

    For each id, the last valid line counts.
    """
    with open(path, "rb") as f:
        data = f.read()
    invalid = []
    records = {}
    for n, raw in enumerate(data.split(b"\n"), 1):
        try:
            text = raw.decode("utf-8").strip()
        except UnicodeDecodeError:
            invalid.append(n)
            continue
        if not text:
            continue
        obj = None
        try:
            obj = json.loads(text)
        except ValueError:
            obj = None
        ok = (
            isinstance(obj, dict)
            and isinstance(obj.get("id"), str)
            and isinstance(obj.get("version"), int)
            and not isinstance(obj.get("version"), bool)
        )
        if not ok:
            invalid.append(n)
            continue
        records[obj["id"]] = (obj["version"], text)
    return invalid, records


def load_state(path):
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        raw = f.read()
    if not raw.strip():
        return {}
    return {str(k): int(v) for k, v in json.loads(raw).items()}


def save_state(path, stored):
    with open(path, "w", encoding="utf-8") as f:
        f.write(json.dumps(stored, sort_keys=True))


def push(api, key, rid, line):
    """Return the HTTP status code, or None if there was no response."""
    url = api.rstrip("/") + "/records/" + urllib.parse.quote(rid, safe="")
    req = urllib.request.Request(
        url,
        data=line.encode("utf-8"),
        method="PUT",
        headers={
            "Authorization": "Bearer " + key,
            "Content-Type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        try:
            e.close()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"]
    key = os.environ["API_KEY"]

    invalid, records = parse_records(find_records_path(input_dir))
    stored = load_state(state_path)

    results = {}  # id -> tuple describing outcome
    for rid in records:
        version, line = records[rid]
        if rid in stored and version <= stored[rid]:
            results[rid] = ("unchanged",)
            continue

        outcome = ("failed",)
        for _ in range(MAX_ATTEMPTS):
            code = push(api, key, rid, line)
            if code is not None and 200 <= code < 300:
                outcome = ("synced",)
                break
            if code is not None and 400 <= code < 500:
                outcome = ("rejected", code)
                break
            # 5xx, other statuses, or no response: retry if attempts remain.
        results[rid] = outcome

        if outcome[0] == "synced":
            stored[rid] = version
            save_state(state_path, stored)

    for n in invalid:
        print("line %d invalid" % n)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        outcome = results[rid]
        counts[outcome[0]] += 1
        if outcome[0] == "rejected":
            print("%s rejected %d" % (rid, outcome[1]))
        else:
            print("%s %s" % (rid, outcome[0]))

    print("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))


if __name__ == "__main__":
    main()

