                    and type(obj.get("version")) is int):
                records[obj["id"]] = (obj["version"], text.encode("utf-8"))
            else:
                invalid.append(n)

    ids = sorted(records, key=lambda s: s.encode("utf-8"))
    results = {}  # id -> (kind, extra)

    for rid in ids:
        version, body = records[rid]
        if rid in last and version <= last[rid]:
            results[rid] = ("unchanged", None)
            continue

        outcome = ("failed", None)
        for _ in range(3):
