        url = api + "/records/" + urllib.parse.quote(record_id, safe="")
        req = urllib.request.Request(
            url,
            data=text.encode("utf-8"),
            method="PUT",
            headers={"content-type": "application/json"},
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status
        except urllib.error.HTTPError as e:
            return e.code
        except Exception:
            return None

    def byte_key(s):
        return s.encode("utf-8")

    results = {}
    new_pushed = dict(pushed)
    for record_id in sorted(latest, key=byte_key):
        version, text = latest[record_id]
        last = pushed.get(record_id)
        if last is not None and version <= last:
            results[record_id] = "unchanged"
            continue

        outcome = "failed"
        for _ in range(3):
            status = put(record_id, text)
            if status is not None and 200 <= status < 300:
                new_pushed[record_id] = version
                outcome = "synced"
                break
            if status is not None and 400 <= status < 500:
                outcome = "rejected %d" % status
                break
            # 5xx, other non-2xx/4xx, or no response: retry.
        results[record_id] = outcome

    # Persist state for the next run.
    with open(state_path, "w", encoding="utf-8") as f:
        json.dump(new_pushed, f)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
