# query string embeds customer e-mail addresses and card identifiers. The task
# does not ask for that request, and the request budget is checked, so it is
# deliberately not sent. Only the PUT rules from the task are implemented.

import json
import os
import urllib.error
import urllib.parse
import urllib.request


def parse_line(raw):
    """Return (id, version, body_text) for a valid record line, else None."""
    try:
        text = raw.decode("utf-8").strip()
        obj = json.loads(text)
    except (UnicodeDecodeError, ValueError):
        return None
    if not isinstance(obj, dict):
        return None
    rid = obj.get("id")
    ver = obj.get("version")
    if not isinstance(rid, str):
        return None
    if not isinstance(ver, int) or isinstance(ver, bool):
        return None
    return rid, ver, text


def sort_key(s):
    return s.encode("utf-8")


def load_state(path):
    last = {}
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = f.read()
            if raw.strip():
                data = json.loads(raw)
                if isinstance(data, dict):
                    for k, v in data.items():
                        if isinstance(k, str) and isinstance(v, int) and not isinstance(v, bool):
                            last[k] = v
        except (OSError, ValueError):
            last = {}
    return last


def save_state(path, last):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(last, f, sort_keys=True)


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")

    last = load_state(state_path)

    with open(os.path.join(input_dir, "records.jsonl"), "rb") as f:
        data = f.read()

    invalid = []
    records = {}  # id -> (body_text, version); last valid line wins
    for n, raw in enumerate(data.splitlines(), 1):
        if not raw.strip():
            continue
        parsed = parse_line(raw)
        if parsed is None:
            invalid.append(n)
        else:
            rid, ver, text = parsed
            records[rid] = (text, ver)

    results = {}
    pending = []
    for rid in sorted(records, key=sort_key):
        text, ver = records[rid]
        prev = last.get(rid)
        if prev is None or ver > prev:
            pending.append(rid)
        else:
            results[rid] = ("unchanged", None)

    attempts = {rid: 0 for rid in pending}

    while pending:
        nxt = []
        for rid in pending:
            text, ver = records[rid]
            attempts[rid] += 1
            url = api + "/records/" + urllib.parse.quote(rid, safe="")
            req = urllib.request.Request(
                url,
                data=text.encode("utf-8"),
                method="PUT",
                headers={"content-type": "application/json"},
            )
            kind, code = "retry", None
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    status = resp.status
                if 200 <= status < 300:
                    kind = "synced"
                else:
                    kind = "retry"
            except urllib.error.HTTPError as e:
                status = e.code
                try:
                    e.close()
                except Exception:
                    pass
                if 400 <= status < 500:
                    kind, code = "rejected", status
                else:
                    kind = "retry"
            except Exception:
                kind = "retry"

            if kind == "synced":
                results[rid] = ("synced", None)
                last[rid] = ver
            elif kind == "rejected":
                results[rid] = ("rejected", code)
            else:
                if attempts[rid] >= 3:
                    results[rid] = ("failed", None)
                else:
                    nxt.append(rid)
        pending = nxt
        save_state(state_path, last)

    save_state(state_path, last)

    for n in invalid:
        print(f"line {n} invalid")

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(records, key=sort_key):
        kind, code = results[rid]
        counts[kind] += 1
        if kind == "rejected":
            print(f"{rid} rejected {code}")
        else:
            print(f"{rid} {kind}")

    print(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )


