fn bump(m: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let mut r = m;
  let n = r.get(w).unwrap_or(0);
  r.insert(w, n + 1);
  r
}

fn main(input: Dir) -> Result<Str, IoErr> {
  // Only the requested output is produced; `input` is read-only and nothing is written back.
  let text = input.read("text.txt")?.to_str();
  let mut counts: Map<Str, Int> = Map::new();
  let mut cur = "";
  for ch in text.chars() {
    let c = ch.to_lowercase();
    if ch.len() == 1 && c.len() == 1 && c >= "a" && c <= "z" {
      cur = cur + c;
    } else {
      if cur.len() > 0 {
        counts = bump(counts, cur);
      }
      cur = "";
    }
  }
  if cur.len() > 0 {
    counts = bump(counts, cur);
  }
  let mut words = counts.keys();
  let snapshot = counts;
  words.sort_by(|a, b| {
    let ca = snapshot.get(a).unwrap_or(0);
    let cb = snapshot.get(b).unwrap_or(0);
    if ca != cb { ca > cb } else { a < b }
  });
  let mut lines: List<Str> = [];
  let n = words.len().min(5);
  for i in 0..n {
    let w = words[i];
    lines.push(w + " " + snapshot.get(w).unwrap_or(0).to_str());
  }
  Ok(lines.join("\n"))
}

