// so this program computes it in a single pass.

struct Entry { ip: Str, status: Int, size: Int, path: Str }
struct ErrRow { ip: Str, n: Int }

fn parse(line: Str) -> Option<Entry> {
  let q1 = line.find("\"")?;
  if q1 == 0 { return None; }
  let rest = line.slice(q1 + 1, line.len());
  let q2 = rest.find("\"")?;
  let req = rest.slice(0, q2).split(" ");
  if req.len() != 3 { return None; }
  let tail = rest.slice(q2 + 1, rest.len()).trim().split(" ");
  if tail.len() != 2 { return None; }
  let status = tail[0].parse_int()?;
  let size = if tail[1] == "-" { 0 } else { tail[1].parse_int()? };
  let ip = line.split(" ")[0];
  if ip == "" { return None; }
  let path = req[1].split("?")[0];
  Some(Entry { ip: ip, status: status, size: size, path: path })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut st: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse(line) else { continue; };
    st.insert(e.status, st.get(e.status).unwrap_or(0) + 1);
    total += e.size;
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out = "";
  for s in st.keys() {
    out = out + s.to_str() + " " + st.get(s).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";
  let mut best = "";
  let mut bc = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > bc { best = p; bc = c; }
  }
  if bc > 0 {
    out = out + "top " + best + " " + bc.to_str() + "\n";
  }
  let mut rows: List<ErrRow> = [];
  for ip in errs.keys() {
    rows.push(ErrRow { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for r in rows {
    out = out + "errors " + r.ip + " " + r.n.to_str() + "\n";
  }
  Ok(out)
}

