  if ip.len() == 0 { return None; }
  let rest = line.slice(q + 1, line.len());
  let e = rest.find("\"")?;
  let words = rest.slice(0, e).split(" ");
  if words.len() < 2 { return None; }
  let parts = rest.slice(e + 1, rest.len()).trim().split(" ");
  if parts.len() != 2 { return None; }
  let status = parts[0].parse_int()?;
  let size = if parts[1] == "-" { 0 } else { parts[1].parse_int()? };
  let mut path = words[1];
  if let Some(i) = path.find("?") {
    path = path.slice(0, i);
  }
  Some(Entry { ip: ip, status: status, size: size, path: path })
}

