  let items: List<Json> = match doc.get("readings") {
    None => [],
    Some(r) => match r.as_list() {
      None => [],
      Some(l) => l,
    },
  };
  let mut n = 0;
  let mut sum = 0;
  let mut mn = 0;
  let mut mx = 0;
  for r in items {
    let Some(tj) = r.get("temp") else { continue; };
    let Some(t) = tj.as_int() else { continue; };
    if n == 0 {
      mn = t;
      mx = t;
    } else {
      mn = mn.min(t);
      mx = mx.max(t);
    }
    sum = sum + t;
    n = n + 1;
  }
  if n == 0 {
    return st.name + " no data";
  }
  st.name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

