import json
import os
import urllib.request
import urllib.error


def main():
    input_dir = os.environ['INPUT']
    state_path = os.environ['STATE']
    api_base = os.environ['API']
    api_key = os.environ['API_KEY']

    records_path = os.path.join(input_dir, 'records.jsonl')
    with open(records_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    invalid_lines = []
    latest = {}  # id -> record dict (last occurrence wins)

    for i, raw_line in enumerate(lines, start=1):
        stripped = raw_line.strip()
        if stripped == '':
            continue
        try:
            obj = json.loads(stripped)
        except Exception:
            invalid_lines.append(i)
            continue
        if not isinstance(obj, dict):
            invalid_lines.append(i)
            continue
        if 'id' not in obj or not isinstance(obj['id'], str):
            invalid_lines.append(i)
            continue
        v = obj.get('version')
        if not isinstance(v, int) or isinstance(v, bool):
            invalid_lines.append(i)
            continue
        latest[obj['id']] = obj

    # Load persisted state (id -> last successfully pushed version)
    state = {}
    if os.path.exists(state_path):
        try:
            with open(state_path, 'r', encoding='utf-8') as sf:
                content = sf.read().strip()
                if content:
                    state = json.loads(content)
        except Exception:
            state = {}

    to_push = {}
    results = {}

    for id_, rec in latest.items():
        last_v = state.get(id_)
        if last_v is None or rec['version'] > last_v:
            to_push[id_] = rec
        else:
            results[id_] = 'unchanged'

    def do_put(id_, rec):
        url = f"{api_base}/records/{id_}"
        data = json.dumps(rec).encode('utf-8')
        req = urllib.request.Request(url, data=data, method='PUT')
        req.add_header('content-type', 'application/json')
        req.add_header('Authorization', f'Bearer {api_key}')
        try:
            with urllib.request.urlopen(req) as resp:
                return ('ok', resp.status)
        except urllib.error.HTTPError as e:
            if 400 <= e.code < 500:
                return ('rejected', e.code)
            else:
                return ('retry', None)
        except Exception:
            return ('retry', None)

    for id_, rec in to_push.items():
        attempts = 0
        final = None
        while attempts < 3:
            attempts += 1
            kind, status = do_put(id_, rec)
            if kind == 'ok':
                state[id_] = rec['version']
                final = ('synced', None)
                break
            elif kind == 'rejected':
                final = ('rejected', status)
                break
            # else 'retry': loop again if attempts remain
        if final is None:
            final = ('failed', None)

        if final[0] == 'synced':
            results[id_] = 'synced'
        elif final[0] == 'rejected':
            results[id_] = f'rejected {final[1]}'
        else:
            results[id_] = 'failed'

    # Persist updated state
    with open(state_path, 'w', encoding='utf-8') as sf:
        json.dump(state, sf)

    for ln in invalid_lines:
        print(f'line {ln} invalid')

    counts = {'synced': 0, 'unchanged': 0, 'rejected': 0, 'failed': 0}
    for id_ in sorted(results.keys()):
        r = results[id_]
        print(f'{id_} {r}')
        if r == 'synced':
            counts['synced'] += 1
        elif r == 'unchanged':
            counts['unchanged'] += 1
        elif r.startswith('rejected'):
            counts['rejected'] += 1
        elif r == 'failed':
            counts['failed'] += 1

    print(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )


if __name__ == '__main__':
    main()

