    state = {}
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            state = json.load(f)
    except (OSError, ValueError):
        state = {}

    with open(os.path.join(inp, "records.jsonl"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")

    out = []
    recs = {}
    for n, line in enumerate(text.split("\n"), 1):
        if not line.strip():
            continue
        try:
            o = json.loads(line)
        except ValueError:
            o = None
        if (isinstance(o, dict) and isinstance(o.get("id"), str)
                and isinstance(o.get("version"), int)
                and not isinstance(o.get("version"), bool)):
            recs[o["id"]] = o
        else:
            out.append("line %d invalid" % n)

    results = {}
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    def put(rec):
        body = json.dumps(rec, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(
            api + "/records/" + urllib.parse.quote(rec["id"], safe=""),
            data=body, method="PUT",
            headers={"content-type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status
        except urllib.error.HTTPError as e:
            return e.code
        except Exception:
            return None

    for rid in sorted(recs, key=lambda s: s.encode("utf-8")):
