        last = state.get(rid)
        if last is not None and not rec["version"] > last:
            results[rid] = "unchanged"
            counts["unchanged"] += 1
            continue
        res = "failed"
        for _ in range(3):
            st = put(rec)
            if st is not None and 200 <= st < 300:
                res = "synced"
                state[rid] = rec["version"]
                break
            if st is not None and 400 <= st < 500:
                res = "rejected %d" % st
                break
        results[rid] = res
        counts[res.split()[0]] += 1

    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        out.append("%s %s" % (rid, results[rid]))
    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))

    with open(state_path, "w", encoding="utf-8") as f:
